"""
    returns the second lowest value in a list of numbers

    Args:
        values: a list of floats

    Returns:
        the second lowst number in values
    """
def get_second_smallest(values: Any) -> object {
    (smallest, second_smallest) = (float("inf"), float("inf"));
    for value in values {
        if (value <= smallest) {
            (smallest, second_smallest) = (value, smallest);
        } elif (value < second_smallest) {
            second_smallest = value;
        }
    }
    return second_smallest;
}

"""
    Returns the ID name for the given ID number, spreadsheet-style, i.e. from a to z,
    then from aa to az, ba to bz, etc., until zz.
    """
def intToID(idnum: Any, prefix: Any) -> object {
    rid = '';
    while (idnum > 0) {
        idnum -= 1;
        rid = chr(((idnum % 26) + ord('a'))) + rid;
        idnum = int((idnum / 26));
    }
    return (prefix + rid);
}

